/*\n  # Seed First Organization from Company Settings\n\n  Copies the existing company_settings record into the organizations table.\n  The DO block in the previous migration may have missed the data due to\n  execution context. This migration ensures the data is populated.\n*/\n\nINSERT INTO organizations (\n  name, slug, logo_url, website, phone, address,\n  primary_contact_email, portal_url, timezone, currency,\n  from_email, from_name, reply_to_email,\n  default_tax_rate, default_invoice_terms, default_deposit_percent,\n  default_project_mgmt_percent, default_system_design_percent,\n  default_cc_fee_percent, default_misc_parts_percent,\n  cc_convenience_fee_enabled, cc_convenience_fee_type,\n  cc_convenience_fee_percentage, cc_convenience_fee_flat_amount,\n  cc_convenience_fee_label, commission_settings,\n  job_module_enabled, job_module_settings,\n  auto_clock_out_enabled, forgot_clock_out_penalty_points,\n  business_day_end_time, auto_clock_out_cutoff_time,\n  auto_clock_out_schedule_enabled, last_auto_clock_out_run,\n  require_gps_for_clock_in, require_gps_for_clock_out,\n  home_clock_notification_enabled, home_location_radius_meters,\n  home_clock_notification_roles, photo_upload_points,\n  on_my_way_sms_template, global_minimum_margin,\n  enforce_minimum_pricing, labor_rate_per_hour,\n  portal_proposals_enabled, portal_projects_enabled,\n  portal_appointments_enabled, portal_invoices_enabled,\n  portal_messages_enabled, portal_vip_services_enabled,\n  portal_punchlist_enabled, enable_public_vip_signup,\n  auto_completion_enabled, auto_completion_requires_approval,\n  auto_completion_reopen_on_delete,\n  auto_archive_declined_proposals_enabled,\n  auto_archive_declined_after_days\n)\nSELECT\n  cs.company_name, 'electronic-life', cs.company_logo_url,\n  cs.website, cs.phone, cs.address,\n  cs.primary_contact_email, cs.portal_url,\n  COALESCE(cs.timezone, 'America/New_York'),\n  COALESCE(cs.currency, 'USD'),\n  cs.from_email, cs.from_name, cs.reply_to_email,\n  cs.default_tax_rate, cs.default_invoice_terms, cs.default_deposit_percent,\n  cs.default_project_mgmt_percent, cs.default_system_design_percent,\n  cs.default_cc_fee_percent, cs.default_misc_parts_percent,\n  cs.cc_convenience_fee_enabled, cs.cc_convenience_fee_type,\n  cs.cc_convenience_fee_percentage, cs.cc_convenience_fee_flat_amount,\n  cs.cc_convenience_fee_label, cs.commission_settings,\n  cs.job_module_enabled, cs.job_module_settings,\n  cs.auto_clock_out_enabled, cs.forgot_clock_out_penalty_points,\n  cs.business_day_end_time, cs.auto_clock_out_cutoff_time,\n  cs.auto_clock_out_schedule_enabled, cs.last_auto_clock_out_run,\n  cs.require_gps_for_clock_in, cs.require_gps_for_clock_out,\n  cs.home_clock_notification_enabled, cs.home_location_radius_meters,\n  cs.home_clock_notification_roles, cs.photo_upload_points,\n  cs.on_my_way_sms_template, cs.global_minimum_margin,\n  cs.enforce_minimum_pricing, cs.labor_rate_per_hour,\n  cs.portal_proposals_enabled, cs.portal_projects_enabled,\n  cs.portal_appointments_enabled, cs.portal_invoices_enabled,\n  cs.portal_messages_enabled, cs.portal_vip_services_enabled,\n  cs.portal_punchlist_enabled, cs.enable_public_vip_signup,\n  cs.auto_completion_enabled, cs.auto_completion_requires_approval,\n  cs.auto_completion_reopen_on_delete,\n  cs.auto_archive_declined_proposals_enabled,\n  cs.auto_archive_declined_after_days\nFROM company_settings cs\nWHERE NOT EXISTS (SELECT 1 FROM organizations)

\n\n-- Seed the secrets from company_settings\nINSERT INTO organization_secrets (\n  organization_id,\n  qbo_connected, qbo_realm_id, qbo_access_token, qbo_refresh_token,\n  qbo_token_expires_at, qbo_payments_enabled,\n  twilio_account_sid, twilio_auth_token, twilio_phone_number,\n  google_maps_api_key, zip_tax_api_key, gemini_api_key, openai_api_key,\n  portal_io_connected, portal_io_access_token, portal_io_token_expires_at\n)\nSELECT\n  o.id,\n  cs.qbo_connected, cs.qbo_realm_id, cs.qbo_access_token, cs.qbo_refresh_token,\n  cs.qbo_token_expires_at, cs.qbo_payments_enabled,\n  cs.twilio_account_sid, cs.twilio_auth_token, cs.twilio_phone_number,\n  cs.google_maps_api_key, cs.zip_tax_api_key, cs.gemini_api_key, cs.openai_api_key,\n  cs.portal_io_connected, cs.portal_io_access_token, cs.portal_io_token_expires_at\nFROM company_settings cs\nCROSS JOIN organizations o\nWHERE NOT EXISTS (SELECT 1 FROM organization_secrets)

\n
